INSERT INTO journal(acteur, changement, motif) VALUES
('reconciliateur', 'Réconciliation replies → outreach.reply_at, toutes les 2 h',
 'Le Réceptionniste enregistrait les réponses sans jamais marquer l''envoi : tout le système lisait 0 réponse alors qu''il en existait 8. Rattrapage par domaine inclus — une réponse vient presque toujours d''une adresse personnelle, pas de la boîte contactée.'),
('instruments', 'Capteurs déterministes posés : enrichissement, veille, dérive des prix, toutes les heures',
 'Le Fureteur a été déclaré mort alors qu''il ajoutait 67 adresses, faute d''une colonne enregistrant quand une adresse est trouvée. On observe désormais de l''extérieur, sans modifier le workflow.'),
('radar', 'Radar de mesure branché : Hugging Face, GitHub, arXiv, Ollama, BOAMP — toutes les 6 h',
 'La Vigie collectait de l''opinion, et ses onze sources mortes étaient toutes des sources d''opinion. Le BOAMP apporte ce qu''aucune autre source ouverte ne donne : le montant réel payé par des acheteurs pour de l''automatisation.'),
('garde_audit', 'Cinq garde-fous bloquants posés sur la chaîne d''audit + 16 cas figés',
 'Un rapport porte la signature de Basile. Sanctions chiffrées non vérifiées, financements indisponibles, promesses certaines, jugements sur le prestataire, références inventées : un rapport qui en contient un ne part pas.');
